async function restoreSupabaseAuthSession(){
  if(!initCloud())return null;
  const url=new URL(location.href);
  const query=new URLSearchParams(url.search);
  const hash=new URLSearchParams((url.hash||"").replace(/^#/ ,""));
  const tokenHash=query.get("token_hash")||hash.get("token_hash");
  const tokenType=query.get("type")||hash.get("type");
  const authError=hash.get("error_description")||query.get("error_description");
  if(authError)throw new Error(authError.replace(/\+/g," "));
  if(tokenHash&&["invite","signup","magiclink","recovery","email"].includes(tokenType||"")){
    const verified=await cloud.auth.verifyOtp({token_hash:tokenHash,type:tokenType});
    if(verified.error)throw verified.error;
    if(verified.data?.session){
      query.delete("token_hash");query.delete("type");
      history.replaceState({},"",url.pathname+(query.toString()?"?"+query.toString():""));
      return verified.data.session;
    }
  }
  const accessToken=hash.get("access_token")||query.get("access_token"),refreshToken=hash.get("refresh_token")||query.get("refresh_token");
  if(accessToken&&refreshToken){
    const restored=await cloud.auth.setSession({access_token:accessToken,refresh_token:refreshToken});
    if(restored.error)throw restored.error;
    if(restored.data?.session){
      ["access_token","refresh_token","expires_at","expires_in","token_type","type"].forEach(k=>query.delete(k));
      history.replaceState({},"",url.pathname+(query.toString()?"?"+query.toString():""));
      return restored.data.session;
    }
  }
  const current=await cloud.auth.getSession();
  if(current.error)throw current.error;
  return current.data?.session||null;
}

async function completeRestoredSession(user){
  if(!initCloud())return;
  let session=null;
  try{session=await restoreSupabaseAuthSession();}catch(e){console.error("Invitation authentication restore failed",e);toast("Invitation verification failed: "+(e?.message||String(e)));return;}
  user=session?.user||null;
  if(!user){toast("Your invitation link is not signed in yet. Open the latest invitation email link again.");return;}
  cloudUser=user;
  if(localStorage.getItem("jengaedu_invited_password_pending_user")===user.id)invitedSessionNeedsPassword=true;
  const invitationToken=new URLSearchParams(location.search).get("invitation");
  let invitedSchoolId=null;
  if(invitationToken){
    const accepted=await cloud.rpc("accept_school_invitation",{p_token:invitationToken});
    if(accepted.error){toast("Invitation could not be accepted: "+accepted.error.message);return;}
    invitedSchoolId=accepted.data||null;
    invitedSessionNeedsPassword=true;
    localStorage.setItem("jengaedu_invited_password_pending_user",user.id);
    const cleanUrl=new URL(location.href);cleanUrl.searchParams.delete("invitation");history.replaceState({},"",cleanUrl.pathname+cleanUrl.search+cleanUrl.hash);
  }
  let memberships=[];
  try{memberships=await fetchSchoolMemberships(user.id,invitedSchoolId);}catch(e){toast("Could not verify school membership: "+(e.message||e));return;}
  const membership=preferredSchoolMembership(memberships);
  if(!membership){if(invitationToken)toast("No active school membership was created. Contact the school administrator.");else toast("This account has no active school workspace.");return;}
  currentUser={username:user.user_metadata?.full_name||"Staff",role:membership.role,id:user.id};
  await activateSchoolMembership(membership,{navigate:false});
  await refreshStaffNavVisibility();
  document.getElementById("login").classList.add("hidden");document.getElementById("app").classList.remove("hidden");
  show(subscriptionRestricted?"Billing":"Dashboard");
  if(invitedSessionNeedsPassword){invitedSessionNeedsPassword=false;openInvitedPasswordSetup();}
}

