async function requestPasswordOtp(){
  const email=v("recoveryEmail").trim(),phone=normalizeKenyanPhone(v("recoveryPhone"));
  if(!email||!phone){toast("Enter the registered email and a valid Kenyan phone number");return}
  if(!cloud||!initCloud()){toast("Supabase is not configured");return}
  const {data,error}=await cloud.functions.invoke("password-recovery",{body:{action:"request",email,phone}});
  if(error||data?.error){toast(data?.error||error.message||"Could not send OTP");return}
  openModal(`<h2>Enter OTP and New Password</h2><p>A 6-digit code was sent to your phone.</p>${field("6-digit OTP","recoveryOtp","","text")}${field("New password","recoveryPassword","","password")}${field("Confirm new password","recoveryPasswordConfirm","","password")}<div class="toolbar"><button onclick="resetPasswordWithOtp('${esc(email)}','${esc(phone)}')">Change Password</button><button class="secondary" onclick="forgot()">Start Again</button></div>`);
}
async function resetPasswordWithOtp(email,phone){
  const code=v("recoveryOtp").trim(),password=v("recoveryPassword"),confirm=v("recoveryPasswordConfirm");
  if(!/^\d{6}$/.test(code)){toast("Enter the 6-digit OTP");return}
  if(password.length<8||password!==confirm){toast("Password must be at least 8 characters and match");return}
  const {data,error}=await cloud.functions.invoke("password-recovery",{body:{action:"reset",email,phone,code,password}});
  if(error||data?.error){toast(data?.error||error.message||"Password reset failed");return}
  closeModal();document.getElementById("loginPass").value="";toast("Password changed successfully. You can now sign in.");
}
async function openRecoveryPassword(){
  openModal(`<h2>Set New Password</h2><p>Choose a new Supabase Auth password.</p>${field("New password","np","","password")}${field("Confirm password","cp","","password")}<div class="toolbar"><button onclick="saveRecoveryPassword()">Update Password</button></div>`);
}
async function saveRecoveryPassword(){
  const a=v("np"),b=v("cp");
  if(a.length<8||a!==b){toast("Password must be 8+ characters and match");return}
  const {error}=await cloud.auth.updateUser({password:a});
  if(error){toast("Password update failed: "+error.message);return}
  closeModal();toast("Password updated successfully");
}
function securitySetup(first=false){
  openModal(`<h2>${first?"First Login Security Setup":"Security Settings"}</h2><p>Your sign-in email is kept private and is not displayed in the school application. Passwords are managed securely by Supabase Authentication.</p>${field("New password","np","","password")}${field("Confirm password","cp","","password")}${field("Recovery phone","phone",db.settings.phone||"")}<div class="toolbar"><button onclick="saveSecurity(${first})">Save Security Settings</button>${!first?'<button class="secondary" onclick="closeModal()">Cancel</button>':""}</div>`);
}
async function saveSecurity(first){
  const a=v("np"),b=v("cp"),ph=v("phone");
  const normalizedPhone=normalizeKenyanPhone(ph);
  if(a.length<8||a!==b){toast("Enter an 8+ character matching password");return}
  if(!normalizedPhone){toast("Enter a valid Kenyan phone number, for example 0712345678 or +254712345678");return}
  if(!cloud||!cloudUser){toast("You must be signed in to Supabase");return}
  const {error}=await cloud.auth.updateUser({password:a});
  if(error){toast("Security update failed: "+error.message);return}
  db.settings.phone=normalizedPhone;
  db.settings.initialPasswordChanged=true;
  save();
  audit("Security settings changed");
  closeModal();
  toast("Security settings saved");
  if(first)show("Dashboard");
}

// Graceful fallback for modules whose original implementation is absent from this source bundle.
// This keeps the dashboard and all other pages usable instead of throwing a ReferenceError.
function renderUnavailableModule(title,description){
  const content=document.getElementById("content");
  if(!content)return;
  content.innerHTML=`<div class="card"><div class="pagehero"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><span class="badge">Module unavailable</span></div><div class="card" style="background:#f8fafc"><h3>This module is not included in the currently deployed source files.</h3><p>Your login and other school workspace modules remain available. No school records have been changed by opening this page.</p><p class="small">To restore the full feature, its original module implementation must be merged into app.js and tested. This safe fallback prevents the missing module from crashing the dashboard.</p><button class="light" onclick="show('Dashboard')">Return to Dashboard</button></div></div>`;
}
function unavailablePage(title,description){return function(){renderUnavailableModule(title,description)}}

let currentPage="Dashboard";
function show(page){
  if(subscriptionRestricted&&page!=="Billing")page="Billing";
  currentPage=page;
  try{
    normalizeDbShape();
    document.getElementById("pageTitle").textContent=page;
    document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("active",b.dataset.page===page));
    document.getElementById("period").textContent=`${db.settings.term}, ${db.settings.year} • ${db.settings.school}`;
    window.scrollTo(0,0);
    const pages={
      Dashboard:dashboard,Learners,Alumni,
      SchoolControls:unavailablePage("School Controls","Manage school-wide policies, permissions and controls."),
      SchoolOperations:unavailablePage("School Operations","Manage daily school operations and administrative workflows."),
      Teachers,StaffManagement,Marks,Exams,
      QuestionPapers:unavailablePage("AI Question Papers","Create and manage curriculum-aligned examination papers."),
      LibraryInventory:unavailablePage("Library & Inventory","Manage library resources, stock and issued items."),
      Rankings,Attendance,Reports,Performance,Fees,Capitation,Timetable,EventsCalendar,Opportunities,Subjects,Settings,
      ParentContacts:unavailablePage("Parent Contacts","Manage parent and guardian contact records."),
      BulkMessaging:unavailablePage("Bulk Messaging","Prepare and send school communications to selected recipients."),
      Billing
    };
    (pages[page]||dashboard)();
  }catch(err){
    console.error("JengaEdu page error:",err);
    const content=document.getElementById("content");
    if(content)content.innerHTML=`<div class="card error-card"><h2>Page could not load</h2><p>The website is signed in, but an application error stopped this page from rendering.</p><p class="small">${esc(err?.message||String(err))}</p><button onclick="location.reload()">Reload Website</button></div>`;
  }
}

