async function Billing(){
 const wasRestricted=subscriptionRestricted;
 const content=document.getElementById("content");
 if(!cloud||!cloudUser||!activeSchool?.id){content.innerHTML='<div class="card"><h2>Subscription & Payments</h2><p>Please sign in to your school account to view billing.</p></div>';return;}
 content.innerHTML='<div class="card"><h2>💳 Subscription & Payments</h2><p>Loading your school subscription…</p></div>';
 const canPay=['school_admin','bursar'].includes(cloudStaffRole);
 const [subRes,invoiceRes]=await Promise.all([
  cloud.from('school_subscriptions').select('status,trial_started_at,trial_ends_at,current_period_start,current_period_end,grace_ends_at').eq('school_id',activeSchool.id).maybeSingle(),
  canPay?cloud.from('subscription_invoices').select('id,invoice_number,amount_due,amount_paid,status,period_start,period_end,due_at,paid_at,created_at').eq('school_id',activeSchool.id).order('created_at',{ascending:false}).limit(12):Promise.resolve({data:[],error:null})
 ]);
 if(subRes.error||invoiceRes.error){content.innerHTML=`<div class="card error-card"><h2>Billing is not ready</h2><p>${esc(subRes.error?.message||invoiceRes.error?.message||'Run the subscription billing migration first.')}</p><p class="small">The application will remain paused until the subscription database and payment functions are configured correctly.</p></div>`;return;}
 const sub=subRes.data, invoices=invoiceRes.data||[];
 if(!sub){subscriptionRestricted=true;content.innerHTML=`<div class="card error-card"><h2>School access paused</h2><p>${esc(subscriptionAccessIssue||"Your school subscription record has not been created. The school workspace is paused until billing is configured.")}</p><p>Contact JengaEdu support after applying the billing SQL migration.</p></div>`;return;}
 const now=Date.now();subscriptionRestricted=!((sub.status==="trialing"&&sub.trial_ends_at&&new Date(sub.trial_ends_at).getTime()+7*86400000>now)||(sub.status==="active"&&sub.current_period_end&&new Date(sub.current_period_end).getTime()+7*86400000>now)||(sub.status==="past_due"&&sub.grace_ends_at&&new Date(sub.grace_ends_at).getTime()>now));
 if(wasRestricted&&!subscriptionRestricted){
  cloudReady=await cloudLoad();
  if(cloudReady){startCloudRefresh();toast("Your subscription is active. School access has been restored.");show("Dashboard");return;}
 }
 const fmt=d=>d?new Date(d).toLocaleDateString('en-KE',{year:'numeric',month:'short',day:'numeric'}):'—';
 const days=sub.trial_ends_at?Math.max(0,Math.ceil((new Date(sub.trial_ends_at)-Date.now())/86400000)):0;
 const statusLabel={pending_approval:'Awaiting approval',trialing:'Free trial',active:'Active',past_due:'Payment due',suspended:'Suspended',cancelled:'Cancelled'}[sub.status]||sub.status;
 const rows=invoices.map(i=>`<tr><td>${esc(i.invoice_number)}</td><td>${fmt(i.period_start)} – ${fmt(i.period_end)}</td><td>KSh ${Number(i.amount_due).toLocaleString('en-KE')}</td><td>${esc(i.status)}</td><td>${fmt(i.paid_at)}</td></tr>`).join('');
 content.innerHTML=`<div class="pagehero"><div><h2>💳 Subscription & Payments</h2><p>${esc(activeSchool.name)} · One subscription covers the entire school.</p></div><span class="badge bright">${esc(statusLabel)}</span></div>
 <div class="grid"><div class="card"><div class="small">Termly subscription</div><h2>KSh 3,000</h2><p class="small">Per school · per academic term</p></div><div class="card"><div class="small">Subscription status</div><h2>${esc(statusLabel)}</h2><p class="small">${sub.status==='trialing'?`${days} days remaining · Trial ends ${fmt(sub.trial_ends_at)}`:sub.status==='active'?`Paid through ${fmt(sub.current_period_end)}`:sub.status==='past_due'?`Grace period ends ${fmt(sub.grace_ends_at)}`:'See support for assistance'}</p></div></div>
 <div class="card billing-pay-card"><h3>📲 Pay school subscription with M-Pesa</h3><p class="small">Enter the M-Pesa number that should receive the STK Push. The amount is KSh 3,000 per school per academic term. Access is restored automatically after Safaricom confirms the payment and the server verifies the callback. Never share your M-Pesa PIN.</p>
 ${canPay?`<div class="formgrid"><div class="field"><label>M-Pesa phone number</label><input id="billingPhone" type="tel" inputmode="tel" placeholder="0712345678"></div></div><div class="toolbar"><button class="success" id="billingPayBtn" onclick="startJengaSubscriptionPayment()">Pay KSh 3,000 with M-Pesa</button><button class="light" onclick="Billing()">Refresh payment status</button></div>`:`<p>Only the school administrator or bursar can initiate subscription payment. Contact your school administrator.</p>`}
 <p id="billingMessage" class="small" aria-live="polite"></p></div>
 <div class="card"><h3>Invoices and payment history</h3><div class="tablewrap"><table class="table"><thead><tr><th>Invoice</th><th>Billing period</th><th>Amount</th><th>Status</th><th>Paid on</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No invoices have been generated yet.</td></tr>'}</tbody></table></div></div>
 <div class="card"><h3>Subscription terms</h3><ul><li>A 60-day introductory trial begins after school approval.</li><li>KSh 3,000 per school per academic term (Term 1, Term 2 or Term 3), regardless of the number of teachers or learners. Each confirmed payment covers three months.</li><li>Payments are initiated by the school administrator or bursar using M-Pesa STK Push.</li><li>After the trial and 7-day grace period, the school workspace is paused until a verified payment is received. School records are retained.</li><li>Once the payment callback is verified, the subscription becomes active and access is restored automatically.</li></ul></div>`;
}
async function startJengaSubscriptionPayment(){
 const phone=document.getElementById('billingPhone')?.value?.trim();const btn=document.getElementById('billingPayBtn');const out=document.getElementById('billingMessage');
 if(!phone){if(out)out.textContent='Enter the M-Pesa phone number first.';return;}
 if(btn){btn.disabled=true;btn.textContent='Sending STK Push…';}
 try{
   const {data,error}=await cloud.functions.invoke('create-mpesa-stk',{body:{school_id:activeSchool.id,phone}});
   if(error)throw error;if(data?.error)throw new Error(data.error);
   if(out)out.textContent=data?.already_paid?'This invoice is already paid. Checking your school access…':(data?.message||'STK Push sent. Check your phone and enter your M-Pesa PIN.');
   pollSubscriptionActivation(0);
 }catch(err){if(out)out.textContent='Payment could not be started: '+(err?.message||String(err));}
 finally{if(btn){btn.disabled=false;btn.textContent='Pay KSh 3,000 with M-Pesa';}}
}

function pollSubscriptionActivation(attempt){
  if(attempt>=24)return;
  setTimeout(async()=>{
    const restricted=await checkSubscriptionAccess(activeSchool?.id);
    if(!restricted){
      cloudReady=await cloudLoad();
      if(cloudReady){
        startCloudRefresh();
        toast("M-Pesa payment confirmed. Your school access is active again.");
        show("Dashboard");
        return;
      }
    }
    const message=document.getElementById("billingMessage");
    if(message&&attempt>=23)message.textContent="Payment is not yet confirmed. Use Refresh payment status after you receive the Safaricom confirmation SMS.";
    else if(message)message.textContent="Waiting for Safaricom payment confirmation…";
    if(attempt<23)pollSubscriptionActivation(attempt+1);
  },5000);
}

