function clearReportSearch(){let q=document.getElementById("reportSearch");if(q)q.value="";let c=document.getElementById("f_rc");if(c)c.value="";let st=document.getElementById("f_rs");if(st)st.value="";refreshReportStreams();loadReportLearners()}
async function downloadReportPDF(){
 const target=document.getElementById("reportPdfTarget");
 if(!target){toast("Generate the report first");return}
 const learner=target.querySelector('.prstudent div');
 const name=(learner?.textContent||"learner-report").replace(/[^a-z0-9]+/gi,"-").replace(/^-|-$/g,"").toLowerCase()||"learner-report";
 const stage=document.createElement("div");
 stage.className="pdf-export-stage pdf-single-report";
 stage.style.cssText="position:fixed!important;left:0!important;top:0!important;width:794px!important;height:1123px!important;overflow:hidden!important;background:#fff!important;z-index:2147483647!important;display:block!important;visibility:visible!important;opacity:1!important;pointer-events:none!important;";
 const clone=target.cloneNode(true);
 clone.removeAttribute("id");
 clone.querySelectorAll(".no-print,.toolbar").forEach(x=>x.remove());
 clone.style.cssText="box-sizing:border-box!important;width:794px!important;min-height:1123px!important;height:1123px!important;max-width:none!important;margin:0!important;padding:28px!important;background:#fff!important;display:block!important;visibility:visible!important;opacity:1!important;color:#172033!important;overflow:hidden!important;";
 stage.appendChild(clone); document.body.appendChild(stage);
 try{
   await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
   if(typeof html2canvas!=="function") throw new Error("html2canvas unavailable");
   const canvas=await html2canvas(clone,{scale:2,useCORS:true,allowTaint:false,backgroundColor:"#ffffff",logging:false,scrollX:0,scrollY:0,width:794,height:1123,windowWidth:794,windowHeight:1123});
   if(!canvas.width||!canvas.height) throw new Error("Empty canvas");
   const PDF=window.jspdf?.jsPDF;
   if(!PDF) throw new Error("jsPDF unavailable");
   const pdf=new PDF({unit:"mm",format:"a4",orientation:"portrait",compress:true});
   pdf.addImage(canvas.toDataURL("image/jpeg",0.98),"JPEG",0,0,210,297,undefined,"FAST");
   pdf.save(name+"-report.pdf");
   toast("Downloaded A4 learner report PDF");
 }catch(err){
   console.error("Learner report PDF error:",err);
   try{ if(typeof html2pdf==="function"){ await html2pdf().set({margin:0,filename:name+"-report.pdf",image:{type:"jpeg",quality:.98},html2canvas:{scale:2,useCORS:true,backgroundColor:"#fff",width:794,height:1123},jsPDF:{unit:"mm",format:"a4",orientation:"portrait"},pagebreak:{mode:["avoid-all"]}}).from(clone).save(); toast("Downloaded A4 learner report PDF"); } else throw err; }
   catch(fallback){toast("PDF generation failed. Use Print A4 and choose Save as PDF.");console.error(fallback)}
 }finally{stage.remove()}
}
function pathwayForSubject(subject){
 const s=String(subject||'').toLowerCase();
 if(/mathematics|integrated science|science|agriculture|pre-technical|technology/.test(s))return 'STEM';
 if(/creative arts|sports|physical|music|art/.test(s))return 'Arts & Sports';
 return 'Social Sciences';
}
function reportPathways(ms){
 const groups={'STEM':[],'Arts & Sports':[],'Social Sciences':[]};
 ms.filter(x=>x.m!==undefined&&x.m!==null&&x.m!=='').forEach(x=>groups[pathwayForSubject(x.s)].push(Number(x.m)));
 const vals=Object.entries(groups).map(([name,a])=>({name,total:a.reduce((s,n)=>s+n,0),max:a.length*50,count:a.length,score:a.length?a.reduce((s,n)=>s+n,0)/(a.length*50)*100:0}));
 const active=vals.filter(x=>x.count).sort((a,b)=>b.score-a.score);
 return {vals, strongest:active[0]||null};
}
function reportAssessmentSequence(){
 const termOrder={"Term 1":1,"Term 2":2,"Term 3":3};
 return [...(db.exams||[])].sort((a,b)=>
   Number(a.year||0)-Number(b.year||0) ||
   (termOrder[a.term]||0)-(termOrder[b.term]||0) ||
   String(a.createdAt||a.date||a.id||"").localeCompare(String(b.createdAt||b.date||b.id||""))
 );
}
function reportPreviousAssessment(examId){
 const seq=reportAssessmentSequence(),i=seq.findIndex(x=>String(x.id)===String(examId));
 return i>0?seq[i-1]:null;
}
function reportLearnerAverage(learnerId,examId,className){
 const subjects=subjectsForPeriod(className,
   (db.exams||[]).find(x=>String(x.id)===String(examId))?.year,
   (db.exams||[]).find(x=>String(x.id)===String(examId))?.term);
 const values=subjects.map(subject=>db.marks.find(m=>m.learner===learnerId&&String(m.exam)===String(examId)&&m.subject===subject)?.mark)
   .filter(v=>v!==undefined&&v!==null&&v!=="").map(Number).filter(Number.isFinite);
 return {count:values.length,total:values.reduce((a,b)=>a+b,0),avg:values.length?values.reduce((a,b)=>a+b,0)/values.length:0};
}
function reportTrendHTML(current,previous,label){
 if(previous===null||previous===undefined||!Number.isFinite(Number(previous)))
   return `<span class="report-trend neutral">NEW</span>`;
 const delta=Number(current)-Number(previous),cls=delta>0.05?"up":delta<-.05?"down":"steady";
 const glyph=cls==="up"?"▲":cls==="down"?"▼":"●";
 return `<span class="report-trend ${cls}" title="${esc(label||"Compared with previous assessment")}">${glyph} ${delta>0?"+":""}${delta.toFixed(1)}</span>`;
}
function reportGradeTrendHTML(currentAvg,previousAvg){
 if(previousAvg===null||previousAvg===undefined)return `<span class="report-trend neutral">BASELINE</span>`;
 const rank={"BE2":1,"BE1":2,"AE2":3,"AE1":4,"ME2":5,"ME1":6,"EE2":7,"EE1":8};
 const currentGrade=grade(currentAvg),previousGrade=grade(previousAvg),delta=(rank[currentGrade]||0)-(rank[previousGrade]||0);
 return `<span class="report-trend ${delta>0?"up":delta<0?"down":"steady"}">${delta>0?"▲ GRADE UP":delta<0?"▼ GRADE DOWN":"● SAME GRADE"}</span>`;
}
function reportMiniBars(current,previous){
 const cur=Math.max(0,Math.min(100,Number(current)||0)),prev=previous===null||previous===undefined?null:Math.max(0,Math.min(100,Number(previous)||0));
 return `<div class="report-mini-bars" aria-label="Current ${cur.toFixed(1)} percent${prev===null?"":`, previous ${prev.toFixed(1)} percent`}">
   ${prev===null?"":`<span class="report-bar previous" style="width:${prev}%"></span>`}
   <span class="report-bar current ${prev!==null&&cur<prev?"decline":""}" style="width:${cur}%"></span>
 </div>`;
}
function buildTeacherReportComment(avg,delta,strengths,areas,hasMarks){
 if(!hasMarks)return "Assessment marks have not yet been entered. The class teacher should review the learner's progress once assessment evidence is available.";
 const opening=avg>=40?"The learner has demonstrated excellent achievement and a strong command of the learning areas assessed.":
   avg>=30?"The learner is making good progress and is developing secure understanding across the learning areas.":
   avg>=20?"The learner is making steady progress but would benefit from regular guided practice and timely feedback.":
   "The learner requires focused support, regular practice and close follow-up to strengthen understanding.";
 const progress=delta===null?" There is no earlier assessment available for comparison.":
   delta>0.5?` Performance has improved by ${delta.toFixed(1)} marks on average compared with the previous assessment.`:
   delta<-.5?` The average has declined by ${Math.abs(delta).toFixed(1)} marks; targeted support and follow-up are recommended.`:
   " Performance is broadly consistent with the previous assessment.";
 const strength=strengths.length?` Stronger learning areas include ${strengths.join(" and ")}.`:"";
 const support=areas.length?` Further support is recommended in ${areas.join(" and ")}.`:"";
 return opening+progress+strength+support+" The learner is encouraged to participate actively, complete assigned work and seek clarification whenever necessary.";
}
function buildLearnerReportHTML(l,e,options={}){
 const ex=db.exams.find(x=>String(x.id)===String(e))||{},ss=subjectsForPeriod(l.class,ex.year,ex.term);
 const previousExam=reportPreviousAssessment(e);
 const ms=ss.map(subject=>{
   const current=db.marks.find(x=>x.learner===l.id&&String(x.exam)===String(e)&&x.subject===subject)?.mark;
   const previous=previousExam?db.marks.find(x=>x.learner===l.id&&String(x.exam)===String(previousExam.id)&&x.subject===subject)?.mark:null;
   return {s:subject,m:current,previous};
 });
 const vals=ms.filter(x=>x.m!==undefined&&x.m!==null&&x.m!=="").map(x=>Number(x.m)).filter(Number.isFinite);
 const total=vals.reduce((a,b)=>a+b,0),avg=vals.length?total/vals.length:0;
 const prior=previousExam?reportLearnerAverage(l.id,previousExam.id,l.class):null;
 const overallDelta=prior&&prior.count?avg-prior.avg:null;
 const classLs=db.learners.filter(x=>x.class===l.class&&String(x.stream||"").trim()===String(l.stream||"").trim()&&x.status!=="Archived");
 const ranked=classLs.map(x=>({id:x.id,...calcLearner(x.id,e)})).filter(x=>x.n>0).sort((a,b)=>b.avg-a.avg||b.total-a.total);
 const idx=ranked.findIndex(x=>x.id===l.id),pos=idx>=0?`${idx+1}/${classLs.length}`:"—";
 const sorted=ms.filter(x=>x.m!==undefined&&x.m!==null&&x.m!=="").sort((a,b)=>Number(b.m)-Number(a.m));
 const strengths=sorted.slice(0,2).map(x=>x.s),areas=[...sorted].reverse().slice(0,2).map(x=>x.s);
 const rec=buildTeacherReportComment(avg,overallDelta,strengths,areas,vals.length>0);
 const rows=ms.map(x=>{
   const hasCurrent=x.m!==undefined&&x.m!==null&&x.m!=="",hasPrevious=x.previous!==undefined&&x.previous!==null&&x.previous!=="";
   const cur=hasCurrent?Number(x.m):null,prev=hasPrevious?Number(x.previous):null;
   return `<tr class="${hasCurrent&&hasPrevious&&cur<prev?"report-mark-decline":""}">
     <td>${esc(String(x.s).toUpperCase())}</td>
     <td>${hasCurrent?cur.toFixed(1):"—"}</td>
     <td>${hasCurrent?grade(cur):"—"}</td>
     <td class="report-trend-cell">${reportTrendHTML(cur,prev,previousExam?.name||"Previous assessment")}</td>
     <td>${hasCurrent?reportMiniBars(cur,prev):'<span class="small">Awaiting marks</span>'}</td>
   </tr>`;
 }).join("");
 const paths=reportPathways(ms),pathRows=paths.vals.map(x=>`<div class="pathway-item"><div class="pathway-label"><b>${esc(x.name)}</b><span>${x.count?`${x.total.toFixed(1)}/${x.max} • ${x.score.toFixed(1)}%`:"No marks"}</span></div><div class="pathway-track"><span style="width:${Math.max(0,Math.min(100,x.score))}%"></span></div></div>`).join("");
 const school=esc(db.settings.school||"JengaEdu Comprehensive School"),term=esc(ex.term||db.settings.term),year=esc(String(ex.year||db.settings.year));
 const signatures=db.settings.signatures||{};
 const signatureBlock=(role,label)=>signatures[role]?`<img class="report-staff-signature" src="${esc(signatures[role])}" alt="${esc(label)} signature">`:"";
 const headName=esc(db.settings.headteacherName||"Headteacher");
 const classTeacherName=esc(l.classTeacherName||db.settings.classTeacherName||"Class Teacher");
 return `<div class="printreport class-bulk-report">
 <div class="prhead">${schoolLogoHTML("report-school-logo")}<div class="prschool">${school}</div><div class="prsubtitle">SCHOOL REPORT</div><div class="prmeta">${term} • ${year} • ${esc(ex.name||ex.type||"Assessment")}</div></div>
 <div class="prstudent${l.photoData?" has-learner-photo":""}">
   ${l.photoData?`<div class="report-learner-photo-wrap"><img class="report-learner-photo" src="${esc(l.photoData)}" alt="Learner photograph"></div>`:""}
   <div><b>LEARNER'S NAME</b><br>${esc(l.name)}</div><div><b>ADMISSION NO.</b><br>${esc(l.adm||"—")}</div>
   <div><b>CLASS / STREAM</b><br>${esc(learnerClassLabel(l))}</div><div><b>ASSESSMENT NO.</b><br>${esc(l.assessmentNo||l.assessment||"—")}</div>
 </div>
 <div class="report-kpis">
   <div><b>Total Marks</b><strong>${total.toFixed(1)} / ${vals.length*50}</strong></div>
   <div><b>Average Marks</b><strong>${avg.toFixed(1)} / 50</strong>${reportTrendHTML(avg,prior&&prior.count?prior.avg:null,"Previous overall average")}</div>
   <div><b>Average Grade</b><strong>${vals.length?grade(avg):"—"}</strong>${reportGradeTrendHTML(avg,prior&&prior.count?prior.avg:null)}</div>
   <div><b>Total Points</b><strong>${vals.length}</strong></div><div><b>Class Position</b><strong>${pos}</strong></div>
 </div>
 <div class="report-overall-progress">
   <div><b>Overall performance trend</b><span>${previousExam?`Compared with ${esc(previousExam.name||previousExam.term||"previous assessment")}`:"Previous assessment not available"}</span></div>
   ${reportMiniBars(avg/50*100,prior&&prior.count?prior.avg/50*100:null)}
   <strong class="${overallDelta===null?"neutral":overallDelta>0.05?"up":overallDelta<-.05?"down":"steady"}">${overallDelta===null?"BASELINE":overallDelta>0?`▲ +${overallDelta.toFixed(1)} marks`:overallDelta<0?`▼ ${overallDelta.toFixed(1)} marks`:"● NO CHANGE"}</strong>
 </div>
 <h3 class="report-section-title">Learning Area Performance</h3>
 <table class="prmarks"><thead><tr><th>Learning Area</th><th>Mark / 50</th><th>Grade</th><th>Change</th><th>Progress</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No subjects configured.</td></tr>'}</tbody></table>
 <p class="report-graph-legend"><span class="legend-current"></span> Current assessment <span class="legend-previous"></span> Previous assessment <span class="legend-decline">Red = decline</span></p>
 <h3 class="report-section-title">Pathway Performance Profile</h3><div class="pathway-profile">${pathRows}</div>
 <p class="strong-pathway"><b>Strongest Pathway:</b> ${paths.strongest?`${esc(paths.strongest.name)} (${paths.strongest.score.toFixed(1)}%)`:"Not available — enter marks to calculate."}</p>
 <div class="prrec"><b>Class Teacher's Professional Comment</b><br>${esc(l.teacherReportComment||rec)}</div>
 <div class="prsign">
   <div>${signatureBlock("classTeacher","Class Teacher")}<b>${classTeacherName}</b><br>Class Teacher<br>Signature / Date</div>
   <div>${signatureBlock("headteacher","Headteacher")}<b>${headName}</b><br>${esc(schoolHeadDesignation())}<br>Signature / Date</div>
   <div><b>Parent / Guardian</b><br>____________________<br>Signature / Date</div>
 </div>
 <footer class="individual-school-motto">${esc(db.settings.motto||"")}</footer></div>`;
}
