 const type=document.getElementById("lcType")?.value||"Primary",title=type==="ECDE"?"EARLY CHILDHOOD DEVELOPMENT AND EDUCATION CERTIFICATE OF LEAVING":type==="Junior"?"JUNIOR SCHOOL LEAVING CERTIFICATE":type==="Senior Secondary"?"SENIOR SECONDARY SCHOOL LEAVING CERTIFICATE":"PRIMARY SCHOOL LEAVING CERTIFICATE";
 const val=id=>document.getElementById(id)?.value||"—", fmt=id=>certificateDate(val(id));
 const logo=db.settings.logoData||db.settings.logoUrl||"";
