function syncTimetableMirrorSoon(){if(!cloudReady||!cloud||!activeSchool?.id)return;Promise.resolve(save()).then(ok=>{if(ok!==true)throw new Error("School timetable JSONB save was not confirmed");return syncTimetableMirror()}).catch(e=>{console.warn("JengaEdu timetable relational mirror sync:",e.message||e);toast("Timetable saved, but relational sync needs attention: "+(e.message||e));});}
function canManageSchoolTimetable(){return ["school_admin","headteacher","deputy_headteacher"].includes(String(cloudStaffRole||""));}
function requireTimetableAdmin(){if(!canManageSchoolTimetable()){toast("Timetable administration is restricted to the school administrator, headteacher and deputy headteacher");return false}return true}
async function generateWithConstraintSolver(targetClasses,label){
  if(!canManageSchoolTimetable()){toast("Only a school administrator, headteacher or deputy headteacher can run the optimized timetable generator");return;}
  if(!cloud||!cloudUser||!activeSchool?.id){toast("Sign in to an active school workspace before generating a timetable");return;}
  const targets=[...new Set(targetClasses||[])];if(!targets.length){toast("No classes selected");return;}
  const status=document.getElementById("ttstatus");if(status)status.innerHTML='<span class="small">Connecting to the JengaEdu constraint solver…</span>';
  try{
    const payload=buildConstraintSolverPayload(targets);
    const {data,error}=await cloud.functions.invoke("solve-timetable",{body:payload});
    if(error)throw new Error(error.message||"Constraint solver request failed");
    if(data?.error)throw new Error(data.error);
    if(!Array.isArray(data?.lessons))throw new Error("Solver returned an invalid response");
    const fixedIds=new Set(payload.fixed.filter(x=>targets.includes(x.class)).map(x=>x.id));
    const keep=(db.timetable||[]).filter(x=>!targets.includes(x.class)||!periodMatchV3(x)||fixedIds.has(String(x.id)));
    const generated=data.lessons.map(x=>({id:uid("TT"),class:String(x.class),groupId:x.group_id||x.groupId||"",learnerIds:Array.isArray(x.learner_ids)?x.learner_ids.map(String):[],subject:String(x.subject),teacherId:x.teacher_id||x.teacherId||"",teacher:teacherNameById(x.teacher_id||x.teacherId)||"Unassigned",room:x.room||"",day:String(x.day),time:String(x.time),year:String(db.settings.year),term:db.settings.term,duration:1,blockId:x.block_id||x.blockId||"",blockPosition:Number(x.block_position||x.blockPosition||1),roomRequired:!!x.room_required,solver:"ortools-cp-sat"}));
    const candidate=keep.concat(generated);
    const conflicts=ttmConflictList(candidate.filter(x=>periodMatchV3(x)));
    if(conflicts.length)throw new Error("Solver response failed local integrity validation: "+conflicts.slice(0,3).map(x=>x.type+" conflict").join(", "));
    ttmSnapshot("Before constraint-solver generation: "+label);
    db.timetable=(db.timetable||[]).filter(x=>!targets.includes(x.class)||!periodMatchV3(x)||ttmIsLocked(x)).concat(generated);
    const synced=await save();if(synced!==true)throw new Error("Timetable could not be confirmed in the school database. Refresh before retrying.");
    let normalized={error:null};try{await syncTimetableMirror()}catch(e){normalized.error=e;console.warn("Timetable relational mirror sync failed:",e.message||e);}
    audit("OR-Tools timetable generated for "+label);
    renderTimetableV3(v("tc"));ttmRefreshStatus(v("tc"));
    const unplaced=Array.isArray(data.unplaced)?data.unplaced:[];
    if(status)status.innerHTML=`<div class="ttm-result ${unplaced.length||normalized.error?"warn":"success"}"><b>${generated.length} period slot(s) scheduled.</b> ${unplaced.length} unplaced. Solver: CP-SAT · ${esc(data.status||"completed")} · ${Number(data.wall_time_seconds||0).toFixed(2)}s.${normalized.error?`<p class="dangertext">Relational timetable mirror not synchronized: ${esc(normalized.error.message)}</p>`:""}${unplaced.length?`<ul>${unplaced.slice(0,12).map(x=>`<li>${esc(x.class||"")} · ${esc(x.subject||"")}: ${esc(x.reason||"No feasible slot")}</li>`).join("")}</ul>`:""}</div>`;
    toast(unplaced.length?"Timetable optimized with unplaced lessons to review":"Optimized timetable generated");
  }catch(e){if(status)status.innerHTML=`<span class="dangertext">Constraint solver unavailable: ${esc(e.message||String(e))}</span>`;toast("Timetable solver: "+(e.message||e));}
}
function generateTimetableLegacyV1(){let c=v("tc"),teacher=v("tt"),ss=subjectsFor(c);if(!ss.length){toast("No active subjects for this class");return}let slots=makeSlots(c),freq={};ss.forEach(s=>freq[s]=defaultFreq[s]||4);let assignments=[],used=new Set(),ti=0;for(const s of ss){for(let n=0;n<freq[s];n++){let placed=false;for(let k=0;k<slots.length;k++){let sl=slots[(ti+k)%slots.length],key=sl.day+"|"+sl.time;if(!used.has(key)){assignments.push({id:uid("TT"),class:c,subject:s,teacher:teacher||"Class Teacher",day:sl.day,time:sl.time});used.add(key);ti=(ti+k+1)%slots.length;placed=true;break}}if(!placed)break}}db.timetable=db.timetable.filter(x=>x.class!==c).concat(assignments);save();audit("Timetable generated for "+c);renderTimetable(c);toast("Timetable generated")}
