function saveTeacherLoad(id=""){if(!requireTimetableAdmin())return;const teacherId=v("tlteacher"),c=v("tlclass"),s=v("tlsub"),weekly=Math.max(1,Math.min(20,Number(v("tlfreq")||4)));if(!teacherId||!c||!s){toast("Teacher, class and subject are required");return}if(db.teacherLoads.some(x=>x.teacherId===teacherId&&x.class===c&&x.subject.toLowerCase()===s.toLowerCase()&&x.id!==id)){toast("That teacher assignment already exists");return}const o={id:id||uid("TL"),teacherId,class:c,subject:s,weeklyLessons:weekly,active:true};const i=db.teacherLoads.findIndex(x=>x.id===id);if(i>=0)db.teacherLoads[i]=o;else db.teacherLoads.push(o);save();syncTimetableMirrorSoon();audit(`Teaching assignment saved: ${teacherNameById(teacherId)} — ${c} — ${s}`);closeModal();Teachers();toast("Teaching assignment saved")}
